import { TrustedClientRepository } from 'app/features/access/trusted-client/repository/trusted-client-repository.service';
import {
  TrustedClientFilter,
  TrustedClientProjection,
} from 'app/features/access/trusted-client/model/trusted-client.model';
import { FormControl } from '@angular/forms';
import { Shift } from '@common/data/repository/repository.model';
import { input, effect, Component } from '@angular/core';

@Component({
  selector: 'trusted-client-view-list',
  templateUrl: './trusted-client-view-list.component.html',
  styleUrls: ['./trusted-client-view-list.component.scss'],
  standalone: false,
})
export class TrustedClientViewListComponent {
  filters = input<TrustedClientFilter>();
  actionName = input<string>('trusted-client');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  search = new FormControl<any>(undefined);
  list: Shift<TrustedClientProjection[], TrustedClientFilter>;

  constructor(repository: TrustedClientRepository) {
    this.list = repository.projections([]);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.code) {
      result.code = external.code;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.code) {
      result.code = filter.code;
    }
    if (filter?.order) {
      result.order = filter.order;
    }
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
